        self.assertEqual(max_sum_increasing_subseq([1, 2, 3, 4], 4, 2, 3), 10)

    def test_kth_in_middle(self):
        self.assertEqual(max_sum_increasing_subseq([2, 1, 3, 4], 4, 1, 2), 3)
        self.assertEqual(max_sum_increasing_subseq([10, 5, 20, 12, 30], 5, 2, 4), 32)
